{{- if .Values.rbac.create -}}
apiVersion: rbac.authorization.k8s.io/v1
kind: ClusterRole
metadata:
  name: {{ include "radar.fullname" . }}
  labels:
    {{- include "radar.labels" . | nindent 4 }}
# Keep cache-backed resource rules aligned with ResourcePermissions in
# internal/k8s/capabilities.go and the README's "Supported Resources" table.
rules:
  # Core resources (read-only)
  - apiGroups: [""]
    resources:
      - pods
      - services
      - configmaps
      - events
      - namespaces
      - nodes
      - persistentvolumes
      - persistentvolumeclaims
      - serviceaccounts
      - endpoints
      - limitranges
      - resourcequotas
    verbs: ["get", "list", "watch"]
  - apiGroups:
      - discovery.k8s.io
    resources:
      - endpointslices
    verbs: ["get", "list", "watch"]
  - apiGroups:
      - policy
    resources:
      - poddisruptionbudgets
    verbs: ["get", "list", "watch"]

  # Storage classes (cluster-scoped, separate API group)
  - apiGroups: ["storage.k8s.io"]
    resources:
      - storageclasses
    verbs: ["get", "list", "watch"]

  # Upgrade impact source evidence. These kinds are not cached or browsable;
  # the collector only lists them to inspect kubectl last-applied annotations.
  - apiGroups: ["storage.k8s.io"]
    resources:
      - csistoragecapacities
    verbs: ["list"]
  - apiGroups: ["flowcontrol.apiserver.k8s.io"]
    resources:
      - flowschemas
      - prioritylevelconfigurations
    verbs: ["list"]
  # Removed in Kubernetes 1.25, but required to assess clusters upgrading
  # from a release where PodSecurityPolicy is still served.
  - apiGroups: ["policy"]
    resources:
      - podsecuritypolicies
    verbs: ["list"]

  {{- if .Values.rbac.helm }}
  # Helm write operations require broad permissions because charts can create
  # any Kubernetes resource type. Read access for common resources is granted
  # by other rules in this ClusterRole. Secrets read access is auto-enabled below.
  - apiGroups: ["*"]
    resources: ["*"]
    verbs: ["create", "update", "patch", "delete"]
  {{- end }}

  {{- if or .Values.rbac.secrets .Values.rbac.helm (ne .Values.auth.mode "none") .Values.cloud.enabled }}
  # Secrets access - required for Helm release storage (rbac.helm),
  # showing secrets in the resource browser (rbac.secrets),
  # or Helm visibility when auth is enabled / cloud-mode (Helm reads use the
  # ServiceAccount since users with the K8s 'view' role cannot list secrets)
  - apiGroups: [""]
    resources:
      - secrets
    verbs: ["get", "list", "watch"]
  {{- end }}

  # Workload resources (read-only)
  - apiGroups: ["apps"]
    resources:
      - deployments
      - daemonsets
      - statefulsets
      - replicasets
    verbs: ["get", "list", "watch"]

  # Networking resources (read-only)
  - apiGroups: ["networking.k8s.io"]
    resources:
      - ingresses
      - ingressclasses
      - networkpolicies
    verbs: ["get", "list", "watch"]

  # Scheduling / runtime / coordination metadata (read-only). PriorityClass
  # and RuntimeClass are cluster-scoped infra; Leases are namespaced but
  # surface in the resource browser and feed GitOps controller readiness.
  - apiGroups: ["scheduling.k8s.io"]
    resources:
      - priorityclasses
    verbs: ["get", "list", "watch"]
  - apiGroups: ["node.k8s.io"]
    resources:
      - runtimeclasses
    verbs: ["get", "list", "watch"]
  - apiGroups: ["coordination.k8s.io"]
    resources:
      - leases
    verbs: ["get", "list", "watch"]

  # Batch resources (read-only)
  - apiGroups: ["batch"]
    resources:
      - jobs
      - cronjobs
    verbs: ["get", "list", "watch"]

  # Autoscaling resources (read-only)
  - apiGroups: ["autoscaling"]
    resources:
      - horizontalpodautoscalers
    verbs: ["get", "list", "watch"]

  # Authorization (required for capability detection via SelfSubjectAccessReview)
  - apiGroups: ["authorization.k8s.io"]
    resources:
      - selfsubjectaccessreviews
    verbs: ["create"]

  {{- if or .Values.rbac.viewRBAC (ne .Values.auth.mode "none") .Values.cloud.enabled }}
  # RBAC objects (read): powers the resource browser's RBAC views and the
  # per-ServiceAccount "blast radius" Permissions panel on Pod/Workload pages.
  # Auto-enabled when auth is on or in cloud mode — there, every RBAC read is
  # re-checked against the requesting user's own permissions, so the shared
  # informer cache cannot leak the cluster's authorization graph. For no-auth
  # installs it stays opt-in via rbac.viewRBAC, since cache-served reads there
  # are not gated per-user and would expose the graph to any viewer.
  - apiGroups: ["rbac.authorization.k8s.io"]
    resources:
      - roles
      - rolebindings
      - clusterroles
      - clusterrolebindings
    verbs: ["get", "list", "watch"]
  {{- end }}

  {{- if or .Values.rbac.viewWebhooks (ne .Values.auth.mode "none") .Values.cloud.enabled }}
  # Admission webhook configurations (read): surfaces the cluster's admission
  # plane (Gatekeeper, Kyverno, image scanners, DLP, etc.) in the resource
  # browser. Auto-enabled under auth/cloud for the same reason as viewRBAC —
  # responses are re-checked per user. For no-auth installs this is opt-in
  # since the configurations reveal which controls are enforced (and where the
  # gaps are), which is recon value for a low-trust viewer.
  - apiGroups: ["admissionregistration.k8s.io"]
    resources:
      - mutatingwebhookconfigurations
      - validatingwebhookconfigurations
    verbs: ["get", "list", "watch"]
  {{- end }}

  {{- if .Values.rbac.podLogs }}
  # Pod logs (opt-in - enables log viewer)
  - apiGroups: [""]
    resources:
      - pods/log
    verbs: ["get"]
  {{- end }}

  {{- if .Values.rbac.podExec }}
  # Pod exec (opt-in - enables terminal feature)
  - apiGroups: [""]
    resources:
      - pods/exec
    verbs: ["create"]
  {{- end }}

  {{- if .Values.rbac.portForward }}
  # Port forwarding (opt-in - enables port forward feature)
  - apiGroups: [""]
    resources:
      - pods/portforward
    verbs: ["create"]
  {{- end }}

  {{- if .Values.rbac.traffic }}
  # Traffic visibility (Hubble/Cilium) - scoped to only the TLS cert secret
  - apiGroups: [""]
    resources:
      - secrets
    resourceNames:
      - hubble-relay-client-certs
    verbs: ["get"]
  {{- end }}

  {{- if .Values.rbac.metrics }}
  # Metrics (CPU/memory utilization) from metrics-server via the
  # metrics.k8s.io aggregated API. Read-only.
  - apiGroups: ["metrics.k8s.io"]
    resources:
      - pods
      - nodes
    verbs: ["get", "list"]
  {{- end }}

  # CRD discovery
  - apiGroups: ["apiextensions.k8s.io"]
    resources:
      - customresourcedefinitions
    verbs: ["get", "list", "watch"]

  # CRD access
  {{- if .Values.rbac.crdGroups.all }}
  # Wildcard access to all CRDs (rbac.crdGroups.all=true)
  - apiGroups: ["*"]
    resources: ["*"]
    verbs: ["get", "list", "watch"]
  {{- else }}
  # Per-group CRD access
  {{- if .Values.rbac.crdGroups.apiRegistration }}
  - apiGroups: ["apiregistration.k8s.io"]
    resources: ["*"]
    verbs: ["get", "list", "watch"]
  {{- end }}
  {{- if .Values.rbac.crdGroups.argo }}
  - apiGroups: ["argoproj.io"]
    resources: ["*"]
    verbs: ["get", "list", "watch"]
  {{- end }}
  {{- if .Values.rbac.crdGroups.awx }}
  - apiGroups: ["awx.ansible.com"]
    resources: ["*"]
    verbs: ["get", "list", "watch"]
  {{- end }}
  {{- if .Values.rbac.crdGroups.certManager }}
  # acme.cert-manager.io carries Orders + Challenges — the ACME issuance flow
  # surfaced when diagnosing a stuck Certificate.
  - apiGroups: ["cert-manager.io", "acme.cert-manager.io"]
    resources: ["*"]
    verbs: ["get", "list", "watch"]
  {{- end }}
  {{- if .Values.rbac.crdGroups.cilium }}
  - apiGroups: ["cilium.io"]
    resources: ["*"]
    verbs: ["get", "list", "watch"]
  {{- end }}
  {{- if .Values.rbac.crdGroups.cloudnativePg }}
  - apiGroups: ["postgresql.cnpg.io"]
    resources: ["*"]
    verbs: ["get", "list", "watch"]
  {{- end }}
  {{- if .Values.rbac.crdGroups.clusterApi }}
  - apiGroups:
      - "cluster.x-k8s.io"
      - "infrastructure.cluster.x-k8s.io"
      - "controlplane.cluster.x-k8s.io"
      - "bootstrap.cluster.x-k8s.io"
      - "addons.cluster.x-k8s.io"
    resources: ["*"]
    verbs: ["get", "list", "watch"]
  {{- end }}
  {{- if .Values.rbac.crdGroups.contour }}
  - apiGroups: ["projectcontour.io"]
    resources: ["*"]
    verbs: ["get", "list", "watch"]
  {{- end }}
  {{- if .Values.rbac.crdGroups.crossplane }}
  - apiGroups: ["crossplane.io", "pkg.crossplane.io", "apiextensions.crossplane.io", "helm.crossplane.io", "kubernetes.crossplane.io"]
    resources: ["*"]
    verbs: ["get", "list", "watch"]
  {{- end }}
  {{- if .Values.rbac.crdGroups.descheduler }}
  - apiGroups: ["descheduler.alpha.kubernetes.io"]
    resources: ["*"]
    verbs: ["get", "list", "watch"]
  {{- end }}
  {{- if .Values.rbac.crdGroups.envoyGateway }}
  - apiGroups: ["gateway.envoyproxy.io"]
    resources: ["*"]
    verbs: ["get", "list", "watch"]
  {{- end }}
  {{- if .Values.rbac.crdGroups.externalDns }}
  - apiGroups: ["externaldns.k8s.io"]
    resources: ["*"]
    verbs: ["get", "list", "watch"]
  {{- end }}
  {{- if .Values.rbac.crdGroups.externalSecrets }}
  - apiGroups: ["external-secrets.io"]
    resources: ["*"]
    verbs: ["get", "list", "watch"]
  {{- end }}
  {{- if .Values.rbac.crdGroups.flux }}
  - apiGroups: ["source.toolkit.fluxcd.io", "kustomize.toolkit.fluxcd.io", "helm.toolkit.fluxcd.io", "notification.toolkit.fluxcd.io", "image.toolkit.fluxcd.io"]
    resources: ["*"]
    verbs: ["get", "list", "watch"]
  {{- end }}
  {{- if .Values.rbac.crdGroups.gatewayApi }}
kind: Deployment
metadata:
  name: {{ include "radar.fullname" . }}
  labels:
    {{- include "radar.labels" . | nindent 4 }}
spec:
  replicas: {{ .Values.replicaCount }}
  {{- if and .Values.persistence.enabled (eq .Values.timeline.storage "sqlite") }}
  strategy:
    type: Recreate
  {{- end }}
  selector:
    matchLabels:
      {{- include "radar.selectorLabels" . | nindent 6 }}
  template:
    metadata:
      {{- with .Values.podAnnotations }}
      annotations:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      labels:
        {{- include "radar.selectorLabels" . | nindent 8 }}
        {{- with .Values.podLabels }}
        {{- toYaml . | nindent 8 }}
        {{- end }}
    spec:
      {{- with .Values.imagePullSecrets }}
      imagePullSecrets:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      serviceAccountName: {{ include "radar.serviceAccountName" . }}
      securityContext:
        {{- toYaml .Values.podSecurityContext | nindent 8 }}
      {{- with .Values.initContainers }}
      initContainers:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      containers:
        - name: {{ .Chart.Name }}
          securityContext:
            {{- toYaml .Values.securityContext | nindent 12 }}
          image: "{{ .Values.image.repository }}:{{ .Values.image.tag | default .Chart.AppVersion }}"
          imagePullPolicy: {{ .Values.image.pullPolicy }}
          args:
            - --port={{ .Values.service.port }}
            - --listen-address=0.0.0.0
            - --no-browser
            {{- if $basePath }}
            - {{ printf "--base-path=%s" $basePath | quote }}
            {{- end }}
            - --timeline-storage={{ .Values.timeline.storage }}
            {{- if eq .Values.timeline.storage "sqlite" }}
            - --timeline-db={{ .Values.timeline.dbPath }}
            {{- if .Values.timeline.retention }}
            - --timeline-retention={{ .Values.timeline.retention }}
            {{- end }}
            {{- if .Values.timeline.maxSize }}
            - --timeline-max-size={{ .Values.timeline.maxSize }}
            {{- end }}
            {{- end }}
            - --history-limit={{ .Values.timeline.historyLimit }}
            {{- if .Values.traffic.prometheusUrl }}
            - --prometheus-url={{ .Values.traffic.prometheusUrl }}
            {{- end }}
            {{- range $k, $v := .Values.traffic.prometheusHeaders }}
            - {{ printf "--prometheus-header=%s=%s" $k $v | quote }}
            {{- end }}
            {{- range $k, $v := .Values.traffic.prometheusHeadersFromEnv }}
            - {{ printf "--prometheus-header-from-env=%s=%s" $k $v | quote }}
            {{- end }}
            {{- if not .Values.mcp.enabled }}
            - --no-mcp
            {{- end }}
            {{- if .Values.debug.image }}
            - --debug-image={{ .Values.debug.image }}
            {{- end }}
            {{- if .Values.listPageSize }}
            - --list-page-size={{ .Values.listPageSize }}
            {{- end }}
            {{- if ne .Values.auth.mode "none" }}
            - {{ printf "--auth-mode=%s" .Values.auth.mode | quote }}
            - {{ printf "--auth-cookie-ttl=%s" .Values.auth.cookieTTL | quote }}
            {{- if .Values.auth.proxy.userHeader }}
            - {{ printf "--auth-user-header=%s" .Values.auth.proxy.userHeader | quote }}
            {{- end }}
            {{- if .Values.auth.proxy.groupsHeader }}
            - {{ printf "--auth-groups-header=%s" .Values.auth.proxy.groupsHeader | quote }}
            {{- end }}
            {{- if .Values.auth.proxy.logoutURL }}
            - {{ printf "--auth-proxy-logout-url=%s" .Values.auth.proxy.logoutURL | quote }}
            {{- end }}
            {{- if .Values.auth.oidc.issuerURL }}
            - {{ printf "--auth-oidc-issuer=%s" .Values.auth.oidc.issuerURL | quote }}
            {{- end }}
            {{- if .Values.auth.oidc.internalIssuerURL }}
            - {{ printf "--auth-oidc-internal-issuer=%s" .Values.auth.oidc.internalIssuerURL | quote }}
{{- if and .Values.persistence.enabled (eq .Values.timeline.storage "sqlite") -}}
apiVersion: v1
kind: PersistentVolumeClaim
metadata:
  name: {{ include "radar.fullname" . }}
  labels:
    {{- include "radar.labels" . | nindent 4 }}
spec:
  accessModes:
    - {{ .Values.persistence.accessMode }}
  {{- if .Values.persistence.storageClassName }}
  storageClassName: {{ .Values.persistence.storageClassName | quote }}
  {{- end }}
  resources:
    requests:
      storage: {{ .Values.persistence.size }}
{{- end }}
apiVersion: v1
kind: Service
metadata:
  name: {{ include "radar.fullname" . }}
  labels:
    {{- include "radar.labels" . | nindent 4 }}
  {{- with .Values.service.annotations }}
  annotations:
    {{- toYaml . | nindent 4 }}
  {{- end }}
spec:
  type: {{ .Values.service.type }}
  ports:
    - port: {{ .Values.service.port }}
      targetPort: http
      protocol: TCP
      name: http
  selector:
    {{- include "radar.selectorLabels" . | nindent 4 }}

