{
  "name": "get_dashboard",
  "description": "Use for inventory-style cluster or namespace health triage, like `kubectl get all` plus detected problems and warning events in one call. Returns resource counts, failing pods, unhealthy workloads, Warning-event groups (warningGroups: up to 20, ordered by lastSeen descending; use lastSeen for liveness, count for cumulative occurrence volume, and objectCount for breadth — objects is a capped sample of up to 3 involved resources, objectsTruncated flags more; if warningGroupsTruncated, more groups exist — use get_events with namespace/kind/name and a higher limit), and Helm release status so you can rank likely suspects before calling get_resource or logs. Routing: unknown broken thing -> issues; content/name search -> search; service routing/dependencies -> get_topology or get_neighborhood; inventory/counts/Helm/events overview -> get_dashboard. Use namespace for app-local triage; omit it when the root may be cluster-scoped.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "namespace": {
        "type": "string",
        "description": "filter to a specific namespace. Use when triaging one app/tenant namespace before drilling into individual resources."
      }
    },
    "additionalProperties": false
  }
}
{
  "name": "get_pod_logs",
  "description": "Use only after narrowing to a specific Pod/container. Returns diagnostically relevant log lines (errors, panics, stack traces, warnings) or falls back to recent tail lines. When grep is set, it replaces diagnostic filtering and returns only regex matches, like `kubectl logs | grep PATTERN`. Use it when you know an error string, request path, service name, or trace id. For broad incidents, first use issues, get_dashboard, search, list_resources, or get_neighborhood to avoid reading logs from many unrelated pods. If the target is a config value, feature flag, CRD field, env ref, or YAML/spec content, use search rather than logs.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "namespace": {
        "type": "string",
        "description": "pod namespace"
      },
      "name": {
        "type": "string",
        "description": "pod name"
      },
      "container": {
        "type": "string",
        "description": "container name, defaults to first container"
      },
      "tail_lines": {
        "type": "integer",
        "description": "number of lines to fetch from the end (default 200)"
      },
      "grep": {
        "type": "string",
        "description": "optional regex; when set, only matching lines are returned, like kubectl logs | grep PATTERN; when omitted, lines are auto-filtered for diagnostic relevance"
      },
      "since": {
        "type": "string",
        "description": "only return logs newer than this duration (e.g. 30s, 10m, 1h), like kubectl logs --since"
      },
      "previous": {
        "type": "boolean",
        "description": "return logs from the previous terminated container instance (e.g. for CrashLoopBackOff diagnosis), like kubectl logs -p"
      }
    },
    "required": [
      "namespace",
      "name"
    ],
    "additionalProperties": false
  }
}

