const podList = await tools.mcp__radar_mcp__list_resources({kind:"Pod",namespace:"radar",context:"summary"});
let podName;
for (const c of (podList?.content ?? [])) {
  if (c.type === "text") {
    const rows = JSON.parse(c.text);
    podName = rows[0]?.name;
    text(`pod_inventory=${c.text}`);
  }
}
const results = await Promise.all([
  tools.mcp__radar_mcp__get_pod_logs({name:podName,namespace:"radar",tail_lines:20,since:"10m"}),
  tools.mcp__radar_mcp__list_helm_releases({}),
  tools.mcp__radar_mcp__top_resources({kind:"pods",limit:5,sort:"cpu"})
]);
for (let i=0;i<results.length;i++) {
  text(`--- ${i+1} ---`);
  const r = results[i];
  if (r?.isError) text("tool_error=true");
  for (const c of (r?.content ?? [])) {
    if (c.type === "text") text(c.text);
    else if (c.type === "image") image(c);
  }
}

