function parseStored(key) {
  const r=load(key);
  const s=r?.content?.find(x=>x.type==="text")?.text;
  return JSON.parse(s);
}
const root=parseStored("sp_root");
const parent=parseStored("sp_longhorn_parent");
const child=parseStored("sp_longhorn_child");
function appSummary(v) {
  const s=v.resource?.status || {};
  return {
    name:v.resource?.metadata?.name,
    generation:v.resource?.metadata?.generation,
    source:v.resource?.spec?.source,
    sync:s.sync,
    health:s.health,
    reconciledAt:s.reconciledAt,
    operation:s.operationState && {
      phase:s.operationState.phase,
      startedAt:s.operationState.startedAt,
      finishedAt:s.operationState.finishedAt,
      message:s.operationState.message,
      revision:s.operationState.syncResult?.revision,
      resources:s.operationState.syncResult?.resources
    },
    history:(s.history||[]).map(h=>({
      id:h.id, revision:h.revision, deployStartedAt:h.deployStartedAt,
      deployedAt:h.deployedAt, targetRevision:h.source?.targetRevision
    })).slice(-10)
  };
}
text(JSON.stringify({
  root:appSummary(root),
  longhornParent:appSummary(parent),
  longhornChild:appSummary(child)
}, null, 2));

