const [crd, appEvents] = await Promise.all([
  tools.mcp__radar_mcp__get_resource({
    kind: "CustomResourceDefinition",
    group: "apiextensions.k8s.io",
    name: "applications.argoproj.io",
    context: "none"
  }),
  tools.mcp__radar_mcp__get_events({
    namespace: "argocd",
    kind: "Application",
    name: "root",
    limit: 50
  })
]);
store("sp_argocd_crd", crd);
text(JSON.stringify({ crd, appEvents }));

const r = await tools.update_plan({
  explanation: "Live reproduction and evidence collection are complete. Netdata supplied the missing capacity telemetry and the Argo Application histories established the Longhorn event order.",
  plan: [
    { step: "Phase 1 — reproduce current health, capacity, issue, and GitOps symptoms and collect exact errors/recent changes", status: "completed" },
    { step: "Phase 2 — compare failing resources with healthy/live and desired/reference patterns", status: "in_progress" },
    { step: "Phase 3 — state one root-cause hypothesis per anomaly and test it with read-only evidence", status: "pending" },
    { step: "Report confirmed causes, residual uncertainty, and separately scoped remediation options", status: "pending" }
  ]
});
text(r);

const r = await tools.web__run({search_query:[
  {q:"site:radarhq.io/docs Prometheus metrics-server capacity Radar Kubernetes"},
  {q:"site:kubernetes.io/docs CustomResourceDefinition metadata generation status subresource generation increments"},
  {q:"site:longhorn.io/docs instance manager PodDisruptionBudget node drain"},
  {q:"site:github.com/longhorn/longhorn v1.12.0 preUpgradeChecker jobEnabled Argo CD"}
],"response_length":"long"}); text(r)

