  cmd: "sed -n '1,320p' /Users/basher8383/.agents/skills/defuddle/SKILL.md",
  workdir: "/Users/basher8383/3I/lab/mothership-gitops",
  yield_time_ms: 10000,
  max_output_tokens: 16000
});
text(r.output);

