  cmd: "command -v defuddle\ndefuddle parse https://radarhq.io/docs --md",
  workdir: "/Users/basher8383/3I/lab/mothership-gitops",
  yield_time_ms: 30000,
  max_output_tokens: 16000
});
text(r.output);

const r = await tools.exec_command({
  cmd: "defuddle parse https://radarhq.io/docs/features/capacity --md",
  workdir: "/Users/basher8383/3I/lab/mothership-gitops",
  yield_time_ms: 30000,
  max_output_tokens: 16000
});
text(r.output);

const r = await tools.exec_command({
  cmd: "sed -n '1,240p' /Users/basher8383/.codex/plugins/cache/openai-curated-remote/superpowers/6.2.0/skills/verification-before-completion/SKILL.md",
