 99	// Wraps a byte stream with an idle timeout that resets on each received chunk.
100	// If no data arrives within the timeout window, the stream terminates cleanly
101	// (returns None). This protects against dead upstream connections mid-stream
102	// without killing healthy long-running SSE streams that send periodic data.
103	pin_project_lite::pin_project! {
104	    struct IdleTimeoutStream<S> {
105	        #[pin]
106	        inner: S,
107	        #[pin]
108	        deadline: Sleep,
109	        timeout: Duration,
110	        timed_out: bool,
111	    }
112	}
113	
114	impl<S> IdleTimeoutStream<S> {
115	    fn new(inner: S, timeout: Duration) -> Self {
116	        Self {
117	            inner,
118	            deadline: tokio::time::sleep(timeout),
119	            timeout,
120	            timed_out: false,
121	        }
122	    }
123	}
124	
125	impl<S, E> Stream for IdleTimeoutStream<S>
126	where
127	    S: Stream<Item = Result<Bytes, E>>,
128	    E: Into<Box<dyn std::error::Error + Send + Sync>>,
129	{
130	    type Item = Result<Bytes, Box<dyn std::error::Error + Send + Sync>>;
131	
132	    fn poll_next(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Option<Self::Item>> {
133	        let mut this = self.project();
134	
135	        if *this.timed_out {
136	            return Poll::Ready(None);
137	        }
138	
139	        if this.deadline.as_mut().poll(cx).is_ready() {
140	            *this.timed_out = true;
141	            warn!("upstream idle timeout after {}s", this.timeout.as_secs());
142	            return Poll::Ready(None);
143	        }
144	
145	        match this.inner.poll_next(cx) {
146	            Poll::Ready(Some(Ok(bytes))) => {
147	                this.deadline
148	                    .reset(tokio::time::Instant::now() + *this.timeout);
149	                Poll::Ready(Some(Ok(bytes)))
150	            }
151	            Poll::Ready(Some(Err(e))) => Poll::Ready(Some(Err(e.into()))),
152	            Poll::Ready(None) => Poll::Ready(None),
153	            Poll::Pending => Poll::Pending,
154	        }
155	    }
156	}
