175	/// Proxy an inbound request to upstream with header injection, retries, and failover.
176	///
177	/// Retry strategy per spec: UpstreamTimeout gets 2 retries with 100ms fixed backoff.
178	/// Failover strategy: QuotaExceeded triggers account switch and re-send; Permanent
179	/// errors disable the account and return the error; Transient errors are returned.
180	#[instrument(skip_all, fields(request_id = %request_id, method = %request.method(), path = %request.uri().path()))]
181	pub async fn proxy_request(
182	    state: &ProxyState,
183	    request: axum::http::Request<axum::body::Body>,
184	    request_id: String,
185	) -> Response {
186	    let start = Instant::now();
187	    state
188	        .requests_total
189	        .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
190	    state
191	        .in_flight
192	        .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
193	    let _in_flight_guard = InFlightGuard(state.in_flight.clone());
194	
195	    let method = request.method().clone();
196	    let method_str = method.to_string();
197	    let uri = request.uri().clone();
198	    let path_str = uri.path().to_string();
199	    let pool_mode = if state.provider.needs_body() {
200	        "oauth"
201	    } else {
202	        "passthrough"
203	    };
204	
205	    // SpanRecorder sets OTel span attributes on drop — every exit path gets a
206	    // complete span regardless of how the function returns.
207	    let mut span_recorder = SpanRecorder {
208	        method: method_str.clone(),
209	        path: path_str,
210	        server_address: state.upstream_url.clone(),
211	        request_id: request_id.clone(),
212	        pool_mode: pool_mode.to_string(),
213	        status_code: 500, // default; overwritten before every return
214	        account_id: None,
215	        error_type: None,
216	        failover_attempt: 0,
217	        params: crate::params::ProxyParams::default(),
218	    };
219	
220	    // Build the upstream URL by appending the request path and query

220	    // Build the upstream URL by appending the request path and query
221	    let upstream_url = if let Some(pq) = uri.path_and_query() {
222	        format!("{}{}", state.upstream_url.trim_end_matches('/'), pq)
223	    } else {
224	        state.upstream_url.clone()
225	    };
226	
227	    // Collect original request headers, stripping hop-by-hop, host, and
228	    // content-length. Host carries the proxy's hostname — reqwest sets the
229	    // correct one from the upstream URL. Content-Length must be recalculated
230	    // by reqwest/hyper because OAuth mode re-serializes the body (system
231	    // prompt injection changes byte count). Forwarding the client's original
232	    // Content-Length causes a mismatch that Cloudflare rejects with 400.
233	    //
234	    // Uses append() instead of insert() to preserve multi-value headers
235	    // (e.g. multiple Cookie or Accept-Encoding values from the client).
236	    let mut original_headers = reqwest::header::HeaderMap::new();
237	    for (name, value) in request.headers() {
238	        if !is_hop_by_hop(name.as_str())
239	            && name != axum::http::header::HOST
240	            && name != axum::http::header::CONTENT_LENGTH
