248	        Ok(b) => b,
249	        Err(e) => {
250	            state
251	                .errors_total
252	                .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
253	            error!(error = %e, "failed to read request body");
254	            let status = StatusCode::BAD_REQUEST;
255	            crate::metrics::record_request(
256	                status.as_u16(),
257	                &method_str,
258	                start.elapsed().as_secs_f64(),
259	            );
