261	            span_recorder.status_code = status.as_u16();
262	            return error_response(status, &format!("invalid request body: {e}"), &request_id);
263	        }
264	    };
265	
266	    // Parse body JSON once if the provider needs it (OAuth mode needs body for
267	    // system prompt injection). The parsed value is re-used across failover attempts.
268	    let parsed_body = if state.provider.needs_body() {
269	        match serde_json::from_slice::<serde_json::Value>(&body_bytes) {
270	            Ok(v) => Some(v),
271	            Err(e) => {
272	                state
273	                    .errors_total
274	                    .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
275	                let status = StatusCode::BAD_REQUEST;
276	                crate::metrics::record_request(
277	                    status.as_u16(),
278	                    &method_str,
279	                    start.elapsed().as_secs_f64(),
280	                );
