 55	/// Build the axum router with all routes and shared state.
 56	///
 57	/// Health and metrics endpoints are outside the concurrency limit so that
 58	/// Kubernetes probes and Prometheus scrapes are never blocked by slow proxy
 59	/// requests occupying all `max_connections` slots.
 60	fn build_router(state: AppState, max_connections: usize) -> Router {
 61	    let proxy_routes = Router::new()
 62	        .fallback(proxy_handler)
 63	        .layer(tower::limit::ConcurrencyLimitLayer::new(max_connections));
 64	
 65	    Router::new()
 66	        .route("/health", get(health_handler))
 67	        .route("/metrics", get(metrics_handler))
 68	        .merge(proxy_routes)
 69	        .with_state(state)
 70	}
