   570	/// Build a response from a buffered error body (used after error classification).
   571	fn build_buffered_response(
   572	    status: StatusCode,
   573	    resp_headers: &reqwest::header::HeaderMap,
   574	    body: axum::body::Bytes,
   575	) -> Response {
   576	    let mut response = Response::builder().status(status);
   577	    for (name, value) in resp_headers {
   578	        if !is_hop_by_hop(name.as_str()) {
   579	            response = response.header(name, value);
   580	        }
   581	    }
   582	    response
   583	        .body(axum::body::Body::from(body))
   584	        .unwrap_or_else(|e| {
   585	            error_response(
   586	                StatusCode::INTERNAL_SERVER_ERROR,
   587	                &format!("response build error: {e}"),
   588	                "",
   589	            )
   590	        })
   591	}
