   593	/// Build a streaming response (used for success and passthrough error responses).
   594	/// Wraps the upstream byte stream with an idle timeout that terminates the stream
   595	/// if no data arrives within the given duration.
   596	fn build_streaming_response(
   597	    status: StatusCode,
   598	    resp_headers: &reqwest::header::HeaderMap,
   599	    upstream_response: reqwest::Response,
   600	    request_id: &str,
   601	    idle_timeout: Duration,
   602	) -> Response {
   603	    let mut response = Response::builder().status(status);
   604	    for (name, value) in resp_headers {
   605	        if !is_hop_by_hop(name.as_str()) {
   606	            response = response.header(name, value);
   607	        }
   608	    }
   609	    let idle_stream = IdleTimeoutStream::new(upstream_response.bytes_stream(), idle_timeout);
   610	    response
   611	        .body(axum::body::Body::from_stream(idle_stream))
   612	        .unwrap_or_else(|e| {
   613	            error_response(
   614	                StatusCode::INTERNAL_SERVER_ERROR,
   615	                &format!("response build error: {e}"),
   616	                request_id,
   617	            )
   618	        })
   619	}
