   621	/// Check if a header is hop-by-hop (should be stripped before forwarding)
   622	pub fn is_hop_by_hop(name: &str) -> bool {
   623	    HOP_BY_HOP_HEADERS
   624	        .iter()
   625	        .any(|h| h.eq_ignore_ascii_case(name))
   626	}
