  1	//! Prometheus metrics exposition
  2	//!
  3	//! Registers and exposes the metrics defined in specs/oauth-proxy.md:
  4	//!
  5	//! - `proxy_requests_total` (counter): labels `status`, `method`
  6	//! - `proxy_request_duration_seconds` (histogram): label `status`
  7	//! - `proxy_upstream_errors_total` (counter): label `error_type`
  8	
  9	use metrics_exporter_prometheus::{PrometheusBuilder, PrometheusHandle};
 10	
 11	/// Install the Prometheus recorder and return a handle for rendering metrics.
 12	///
 13	/// Configures `proxy_request_duration_seconds` with histogram buckets so it
 14	/// renders as a Prometheus histogram (with `_bucket` lines for `histogram_quantile()`
 15	/// queries) rather than the default summary. Bucket boundaries cover the range
 16	/// from 5ms to 60s, matching the proxy's configurable timeout range.
 17	///
 18	/// The handle's `render()` method produces the Prometheus text exposition format
 19	/// suitable for serving on a `/metrics` endpoint.
 20	pub fn install_recorder() -> PrometheusHandle {
 21	    PrometheusBuilder::new()
 22	        .set_buckets_for_metric(
 23	            metrics_exporter_prometheus::Matcher::Full(
 24	                "proxy_request_duration_seconds".to_string(),
 25	            ),
 26	            &[
 27	                0.005, 0.01, 0.025, 0.05, 0.1, 0.25, 0.5, 1.0, 2.5, 5.0, 10.0, 30.0, 60.0,
 28	            ],
 29	        )
 30	        .expect("failed to set histogram buckets")
 31	        .install_recorder()
 32	        .expect("failed to install Prometheus recorder")
 33	}
 34	
 35	/// Record a completed proxy request with status code and HTTP method labels.
 36	pub fn record_request(status: u16, method: &str, duration_secs: f64) {
 37	    let status_str = status.to_string();
 38	    metrics::counter!("proxy_requests_total", "status" => status_str.clone(), "method" => method.to_string())
 39	        .increment(1);
 40	    metrics::histogram!("proxy_request_duration_seconds", "status" => status_str)
 41	        .record(duration_secs);
 42	}
 43	
 44	/// Record an upstream error with a classification label.
 45	pub fn record_upstream_error(error_type: &str) {
 46	    metrics::counter!("proxy_upstream_errors_total", "error_type" => error_type.to_string())
 47	        .increment(1);
 48	}
 49	
 50	/// Record a pool account status change (gauge, 1 for current status).
 51	pub fn record_pool_account_status(account_id: &str, status: &str) {
 52	    // Set all status variants to 0 first, then set the current one to 1.
 53	    // This ensures only one status variant is active per account at any time.
 54	    for s in &["available", "cooling_down", "disabled"] {
 55	        metrics::gauge!("pool_account_status", "account_id" => account_id.to_string(), "status" => s.to_string())
 56	            .set(0.0);
 57	    }
 58	    metrics::gauge!("pool_account_status", "account_id" => account_id.to_string(), "status" => status.to_string())
 59	        .set(1.0);
 60	}
 61	
 62	/// Record a pool failover event (account switch due to quota exhaustion).
 63	pub fn record_pool_failover(from_account: &str, reason: &str) {
 64	    metrics::counter!("pool_failovers_total", "from_account" => from_account.to_string(), "reason" => reason.to_string())
 65	        .increment(1);
 66	}
 67	
 68	/// Record a quota exhaustion event for an account.
 69	pub fn record_pool_quota_exhaustion(account_id: &str) {
 70	    metrics::counter!("pool_quota_exhaustions_total", "account_id" => account_id.to_string())
 71	        .increment(1);
 72	}
