 77	    use metrics_exporter_prometheus::PrometheusRecorder;
 78	
 79	    #[test]
 80	    fn record_functions_do_not_panic_without_recorder() {
 81	        // When no recorder is installed, metrics calls are no-ops.
 82	        // This verifies the functions don't panic in test environments.
