 87	    /// Create an isolated recorder/handle pair for unit tests.
 88	    /// Uses build_recorder() instead of install_recorder() to avoid the
 89	    /// global recorder singleton constraint — only one global recorder can
 90	    /// exist per process, and install_recorder() panics on a second call.
 91	    fn isolated_recorder() -> (PrometheusRecorder, PrometheusHandle) {
 92	        let recorder = PrometheusBuilder::new()
 93	            .set_buckets_for_metric(
 94	                metrics_exporter_prometheus::Matcher::Full(
 95	                    "proxy_request_duration_seconds".to_string(),
 96	                ),
 97	                &[
 98	                    0.005, 0.01, 0.025, 0.05, 0.1, 0.25, 0.5, 1.0, 2.5, 5.0, 10.0, 30.0, 60.0,
 99	                ],
100	            )
101	            .expect("failed to set histogram buckets")
102	            .build_recorder();
103	        let handle = recorder.handle();
104	        (recorder, handle)
105	    }
