107	    #[test]
108	    fn record_request_increments_counter_and_histogram() {
109	        // Verifies that record_request() actually writes to the Prometheus
110	        // recorder so that /metrics renders the expected counter and histogram
111	        // lines. Without an installed recorder these calls are silent no-ops,
112	        // which would leave operators with empty dashboards.
113	        let (recorder, handle) = isolated_recorder();
114	        let _guard = metrics::set_default_local_recorder(&recorder);
115	
116	        record_request(200, "GET", 0.042);
117	        record_request(500, "POST", 1.5);
118	
119	        let output = handle.render();
120	        assert!(
121	            output.contains("proxy_requests_total"),
122	            "rendered output must contain proxy_requests_total counter"
123	        );
124	        assert!(
125	            output.contains("status=\"200\""),
126	            "counter must carry status label"
127	        );
128	        assert!(
129	            output.contains("method=\"GET\""),
130	            "counter must carry method label"
131	        );
132	        assert!(
133	            output.contains("status=\"500\""),
134	            "second request status label must appear"
135	        );
136	        assert!(
137	            output.contains("method=\"POST\""),
138	            "second request method label must appear"
139	        );
140	        assert!(
141	            output.contains("proxy_request_duration_seconds_bucket"),
142	            "histogram must render _bucket lines for histogram_quantile() queries"
143	        );
144	    }
