152	        let _guard = metrics::set_default_local_recorder(&recorder);
153	
154	        record_upstream_error("timeout");
155	        record_upstream_error("connection");
156	
157	        let output = handle.render();
158	        assert!(
159	            output.contains("proxy_upstream_errors_total"),
160	            "rendered output must contain proxy_upstream_errors_total counter"
161	        );
162	        assert!(
163	            output.contains("error_type=\"timeout\""),
164	            "error_type label must be recorded"
165	        );
166	        assert!(
167	            output.contains("error_type=\"connection\""),
168	            "distinct error_type values must appear separately"
169	        );
170	    }
