172	    #[test]
173	    fn histogram_buckets_cover_spec_range() {
174	        // The spec requires histogram buckets from 5ms to 60s so that
175	        // histogram_quantile() queries in Grafana/RUNBOOK produce meaningful
176	        // results. Without explicit buckets, metrics-exporter-prometheus
177	        // renders summaries (quantiles) instead of histograms (_bucket lines),
178	        // breaking all RUNBOOK PromQL.
179	        let (recorder, handle) = isolated_recorder();
180	        let _guard = metrics::set_default_local_recorder(&recorder);
181	
182	        record_request(200, "GET", 0.003); // 3ms, below lowest bucket
183	
184	        let output = handle.render();
185	        // Verify specific bucket boundaries from the spec
186	        assert!(output.contains("le=\"0.005\""), "5ms bucket must exist");
187	        assert!(output.contains("le=\"0.01\""), "10ms bucket must exist");
188	        assert!(
189	            output.contains("le=\"60\""),
190	            "60s bucket must exist (upper bound of timeout range)"
191	        );
192	        assert!(
193	            output.contains("le=\"+Inf\""),
194	            "+Inf bucket must exist (Prometheus convention)"
195	        );
196	    }
